        return []

    rows = []
    i = 0
    n = len(text)

    while i < n:
        row = []
        # Bir satırın içindeyiz
        while True:
            # 1. Field (Alan) parse et
            if i < n and text[i] == '"':
                i += 1
                field = ""
                while i < n:
                    if text[i] == '"':
                        if i + 1 < n and text[i+1] == '"':
                            field += '"'
                            i += 2
                        else:
                            i += 1
                            if i < n and text[i] not in (delimiter, "\r", "\n"):
                                raise ValueError("Hatalı tırnak kullanımı.")
                            break
                    else:
                        field += text[i]
                        i += 1
                else:
                    raise ValueError("Kapanmayan tırnak.")
                row.append(field)
            else:
                start = i
                while i < n and text[i] not in (delimiter, "\r", "\n"):
                    i += 1
                row.append(text[start:i])

            # 2. Ayırıcı veya Satır sonu kontrolü
            if i < n and text[i] == delimiter:
                i += 1
                if i == n:  # Satır delimiter ile biterse son alan boştur
                    row.append("")
                    break
            elif i < n and text[i] in "\r\n":
                break  # Satır bitti
            else:
                break  # Metin bitti

        rows.append(row)

        # 3. Satır sonu karakterlerini tüket (CRLF veya LF)
        if i < n and text[i] in "\r\n":
